const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
const num = v => v === '' || v == null ? null : Number(v);
const fmt = v => v == null || Number.isNaN(v) ? '—' : Math.round(v).toLocaleString();
const pct = v => v == null || Number.isNaN(v) ? '—' : `${Number(v).toFixed(1)}%`;
const key = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
let master = [], boundaries = null, trajectories = {}, map, mapReady = false, pinned = [], sort = 'TOT_per_1000', sortDir = 1;
let state = {technology:'Push-Pull',country:'Kenya',adminLevel:'Admin2',adminUnit:'Alego-Usonga',target:'30',deadline:'36',mapMetric:'TOT_per_1000'};

function parseCSV(text) { const out=[]; let row=[], cell='', quote=false; for(let i=0;i<text.length;i++){const c=text[i], n=text[i+1]; if(c==='"'){if(quote&&n==='"'){cell+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(x=>x!==''))out.push(row);row=[];cell='';}else cell+=c;} if(cell||row.length){row.push(cell);out.push(row);} const headers=out.shift(); return out.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??'']))); }
const unique = (rows, field) => [...new Set(rows.map(r=>r[field]).filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true}));
function setOptions(id, values, preferred, label=v=>v){const el=$(id); const keep=values.includes(preferred)?preferred:values[0]; el.innerHTML=values.map(v=>`<option value="${v}">${label(v)}</option>`).join('');el.value=keep;return keep;}
function selected(){return master.find(r=>r.technology===state.technology&&r.country===state.country&&r.admin_level===state.adminLevel&&r.admin_unit===state.adminUnit&&r.target_percent===state.target&&r.deadline_months===state.deadline);}
function cascade(changed){ state.technology=setOptions('#technology',unique(master,'technology'),state.technology); let rows=master.filter(r=>r.technology===state.technology); state.country=setOptions('#country',unique(rows,'country'),state.country); rows=rows.filter(r=>r.country===state.country); state.adminLevel=setOptions('#adminLevel',unique(rows,'admin_level'),state.adminLevel); rows=rows.filter(r=>r.admin_level===state.adminLevel); state.adminUnit=setOptions('#adminUnit',unique(rows,'admin_unit'),state.adminUnit); rows=rows.filter(r=>r.admin_unit===state.adminUnit); state.target=setOptions('#target',unique(rows,'target_percent'),state.target,v=>`${v}%`); rows=rows.filter(r=>r.target_percent===state.target); state.deadline=setOptions('#deadline',unique(rows,'deadline_months'),state.deadline,v=>`${v} months`); render(); }
function crossArea(){return master.filter(r=>r.technology===state.technology&&r.country===state.country&&r.admin_level===state.adminLevel&&r.target_percent===state.target&&r.deadline_months===state.deadline);}
function value(r,f){if(f==='earliest_safe_withdrawal_month')return num(r[f]);return num(r[f]);}
function renderKpis(r){const failed=!r||!r.minimum_TOT; $('#minimumTot').textContent=failed?'Not achieved':fmt(num(r.minimum_TOT)); $('#totPer1000').textContent=failed?'—':num(r.TOT_per_1000).toFixed(1); $('#deadlineAdoption').textContent=failed?'—':pct(num(r.adoption_at_deadline_percent)); $('#deadlineNote').textContent=failed?'within tested ToT range':`${state.target}% target by ${state.deadline} months`; const w=num(r.earliest_safe_withdrawal_month); $('#safeWithdrawal').textContent=w==null?'No safe exit':`Month ${w}`; $('#adoptionAfterExit').textContent=w==null?'—':pct(num(r.adoption_5y_after_percent)); $('#maintained').textContent=r.target_maintained_after_withdrawal==='TRUE'?'Maintained':'Not maintained'; $('#statusText').textContent=r.status||'Scenario unavailable'; $('#scenarioStatus').textContent=`${r.country} · ${r.admin_level} · ${r.admin_unit} · ${r.scenario_id}`;}
function drawTrajectory(r){const svg=$('#trajectoryChart');const t=trajectories[r.scenario_id];$('#trajectoryTitle').textContent=`${r.admin_unit}: adoption through time`;if(!t){svg.innerHTML='<text x="40" y="50">No trajectory is available for this scenario.</text>';return;}const W=700,H=360,m={l:52,r:18,t:22,b:38},x=v=>m.l+v/120*(W-m.l-m.r),y=v=>H-m.b-v/100*(H-m.t-m.b);let h='';for(let v=0;v<=100;v+=20)h+=`<line class="gridline" x1="${m.l}" x2="${W-m.r}" y1="${y(v)}" y2="${y(v)}"/><text class="chart-label" x="${m.l-8}" y="${y(v)+4}" text-anchor="end">${v}%</text>`;for(let v=0;v<=120;v+=24)h+=`<text class="chart-label" x="${x(v)}" y="${H-14}" text-anchor="middle">${v}</text>`;const path=(a,start=0)=>a.map((v,i)=>`${i?'L':'M'}${x(i+start).toFixed(1)},${y(v).toFixed(1)}`).join(' ');h+=`<line class="target-line" x1="${m.l}" x2="${W-m.r}" y1="${y(num(r.target_percent))}" y2="${y(num(r.target_percent))}"/><line class="deadline-line" x1="${x(num(r.deadline_months))}" x2="${x(num(r.deadline_months))}" y1="${m.t}" y2="${H-m.b}"/><path class="series continued" d="${path(t.c)}"/>`;if(t.w.length){h+=`<path class="series withdrawal" d="${path(t.w,t.ws||0)}"/><line class="withdraw-line" x1="${x(t.wm)}" x2="${x(t.wm)}" y1="${m.t}" y2="${H-m.b}"/>`;}h+=`<text class="chart-label" x="${W/2}" y="${H-3}" text-anchor="middle">Months</text>`;svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML=h;}
function popup(r){return `<div class="county-popup"><strong>${r.admin_unit}</strong><dl><div><dt>ToTs / 1,000</dt><dd>${r.minimum_TOT?num(r.TOT_per_1000).toFixed(1):'Not achieved'}</dd></div><div><dt>Minimum ToTs</dt><dd>${r.minimum_TOT||'Not achieved'}</dd></div><div><dt>Safe withdrawal</dt><dd>${num(r.earliest_safe_withdrawal_month)==null?'No safe exit':`Month ${r.earliest_safe_withdrawal_month}`}</dd></div><div><dt>5-year adoption</dt><dd>${pct(num(r.adoption_5y_after_percent))}</dd></div></dl></div>`;}
function mapData(){const rows=crossArea(), byName=new Map(rows.map(r=>[key(r.admin_unit),r]));return {...boundaries,features:boundaries.features.filter(f=>f.properties.country===state.country&&f.properties.admin_level===state.adminLevel).map(f=>{const r=byName.get(key(f.properties.name));return {...f,properties:{...f.properties,scenario_id:r?.scenario_id||'',metric:r&&r.minimum_TOT?value(r,state.mapMetric):null,selected:r?.admin_unit===state.adminUnit}};})};}
function geometryBounds(geometry){const coordinates=[];const collect=value=>{if(typeof value[0]==='number')coordinates.push(value);else value.forEach(collect);};collect(geometry.coordinates);if(!coordinates.length)return null;const xs=coordinates.map(c=>c[0]),ys=coordinates.map(c=>c[1]);return [[Math.min(...xs),Math.min(...ys)],[Math.max(...xs),Math.max(...ys)]];}
function updateMap(){if(!mapReady)return;const data=mapData();const vals=data.features.map(f=>f.properties.metric).filter(v=>Number.isFinite(v));const min=vals.length?Math.min(...vals):0,max=vals.length?Math.max(...vals):1,range=Math.max(max-min,1);map.getSource('areas').setData(data);map.setPaintProperty('area-fill','fill-color',['case',['!=',['get','metric'],null],['step',['get','metric'],'#eef5ef',min+range*.25,'#b8dec2',min+range*.5,'#75b98d',min+range*.75,'#31845c','#0d4d34'],'#dce3df']);map.setFilter('area-selected',['==',['get','selected'],true]);const selectedFeature=data.features.find(f=>f.properties.selected);const bounds=selectedFeature&&geometryBounds(selectedFeature.geometry);if(bounds)map.fitBounds(bounds,{padding:{top:70,right:70,bottom:70,left:70},maxZoom:11,duration:650,essential:true});}
function initMap(){if(map||!boundaries)return;$('#map').innerHTML='';map=new maplibregl.Map({container:'map',style:{version:8,sources:{osm:{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors'}},layers:[{id:'background',type:'background',paint:{'background-color':'#eef3f0'}},{id:'osm',type:'raster',source:'osm',minzoom:0,maxzoom:19}]},center:[21,3],zoom:2.7,attributionControl:true});map.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-right');map.on('load',()=>{map.addSource('areas',{type:'geojson',data:mapData()});map.addLayer({id:'area-fill',type:'fill',source:'areas',paint:{'fill-color':'#75b98d','fill-opacity':.86}});map.addLayer({id:'area-line',type:'line',source:'areas',paint:{'line-color':'#ffffff','line-width':1.5}});map.addLayer({id:'area-selected',type:'line',source:'areas',filter:['==',['get','selected'],true],paint:{'line-color':'#123c2c','line-width':3}});map.on('click','area-fill',e=>{const id=e.features[0].properties.scenario_id;if(!id)return;const r=master.find(x=>x.scenario_id===id);state.adminLevel=r.admin_level;state.adminUnit=r.admin_unit;cascade();new maplibregl.Popup({maxWidth:'290px'}).setLngLat(e.lngLat).setHTML(popup(r)).addTo(map);});map.on('mouseenter','area-fill',()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave','area-fill',()=>map.getCanvas().style.cursor='');mapReady=true;updateMap();});}
function renderTable(){const rows=[...crossArea()].sort((a,b)=>{let av=a[sort],bv=b[sort];if(sort==='target_maintained_after_withdrawal')return String(av).localeCompare(String(bv))*sortDir; if(sort==='admin_unit'||sort==='status')return String(av).localeCompare(String(bv))*sortDir;return ((num(av)??-Infinity)-(num(bv)??-Infinity))*sortDir;});$('#areaRows').innerHTML=rows.map(r=>`<tr class="${r.admin_unit===state.adminUnit?'selected':''}" data-id="${r.scenario_id}"><td><strong>${r.admin_unit}</strong></td><td>${fmt(num(r.survey_n))}</td><td>${r.minimum_TOT?num(r.TOT_per_1000).toFixed(1):'—'}</td><td>${r.minimum_TOT||'Not achieved'}</td><td>${num(r.earliest_safe_withdrawal_month)==null?'No safe exit':`Month ${r.earliest_safe_withdrawal_month}`}</td><td>${pct(num(r.adoption_5y_after_percent))}</td><td>${r.target_maintained_after_withdrawal==='TRUE'?'Maintained':'No'}</td><td>${r.status}</td></tr>`).join('');$$('#areaRows tr').forEach(tr=>tr.onclick=()=>{const r=master.find(x=>x.scenario_id===tr.dataset.id);state.adminUnit=r.admin_unit;$('#adminUnit').value=r.admin_unit;render();});}
function renderPinned(){const wrap=$('#pinnedScenarios');if(!pinned.length){wrap.className='pinned-empty';wrap.textContent='No scenarios pinned.';return;}wrap.className='pinned-grid';wrap.innerHTML=pinned.map(r=>`<article><button data-remove="${r.scenario_id}" aria-label="Remove ${r.admin_unit}">×</button><strong>${r.admin_unit}</strong><span>${r.target_percent}% by ${r.deadline_months} months</span><dl><div><dt>Minimum ToTs</dt><dd>${r.minimum_TOT||'Not achieved'}</dd></div><div><dt>ToTs / 1,000</dt><dd>${r.minimum_TOT?num(r.TOT_per_1000).toFixed(1):'—'}</dd></div><div><dt>Safe exit</dt><dd>${num(r.earliest_safe_withdrawal_month)==null?'No safe exit':`Month ${r.earliest_safe_withdrawal_month}`}</dd></div><div><dt>5-year adoption</dt><dd>${pct(num(r.adoption_5y_after_percent))}</dd></div></dl></article>`).join('');$$('[data-remove]').forEach(b=>b.onclick=()=>{pinned=pinned.filter(r=>r.scenario_id!==b.dataset.remove);renderPinned();});}
function render(){const r=selected();renderKpis(r);drawTrajectory(r);renderTable();renderPinned();const hasBoundary=boundaries.features.some(f=>f.properties.country===r.country&&f.properties.admin_level===r.admin_level&&key(f.properties.name)===key(r.admin_unit));document.querySelector('.map-note').textContent=hasBoundary?'Click an available administrative unit to update the scenario. Boundaries are from geoBoundaries and HDX COD-AB.':`${r.admin_unit} is included in the scenario library, but no matching published boundary is available. Use the comparison table to review this unit.`;$('#provenance').innerHTML=`<dl class="provenance-grid"><div><dt>Scenario ID</dt><dd>${r.scenario_id}</dd></div><div><dt>Survey n</dt><dd>${r.survey_n}</dd></div><div><dt>Sigma</dt><dd>${r.sigma}</dd></div><div><dt>Delta</dt><dd>${r.delta}</dd></div><div><dt>Sigma source</dt><dd>${r.sigma_source}</dd></div><div><dt>Delta source</dt><dd>${r.delta_source}</dd></div><div><dt>Sigma level</dt><dd>${r.sigma_parameter_level}</dd></div><div><dt>Delta level</dt><dd>${r.delta_parameter_level}</dd></div></dl>`;initMap();updateMap();}
async function load(){const [m,b]=await Promise.all([fetch('data/PPT_dashboard_master.csv').then(r=>r.text()),fetch('data/program-boundaries.geojson').then(r=>r.json())]);master=parseCSV(m);boundaries=b;const [ke,ug]=await Promise.all([fetch('data/trajectories-kenya.json').then(r=>r.json()),fetch('data/trajectories-uganda.json').then(r=>r.json())]);trajectories={...ke,...ug};cascade();}
['#technology','#country','#adminLevel','#adminUnit','#target','#deadline'].forEach(id=>$(id).onchange=e=>{const k={technology:'technology',country:'country',adminLevel:'adminLevel',adminUnit:'adminUnit',target:'target',deadline:'deadline'}[id.slice(1)];state[k]=e.target.value;cascade(k);});$('#mapMetric').onchange=e=>{state.mapMetric=e.target.value;updateMap();};$('#pinScenario').onclick=()=>{const r=selected();if(!pinned.some(x=>x.scenario_id===r.scenario_id)&&pinned.length<3)pinned.push(r);renderPinned();};$$('th[data-sort]').forEach(th=>th.onclick=()=>{const k=th.dataset.sort;sortDir=sort===k?-sortDir:1;sort=k;renderTable();});load().catch(e=>{$('#scenarioStatus').textContent='Scenario library could not be loaded.';console.error(e);});
